// upstream-test-harness — the quickjs test shell for the UPSTREAM suite in
// OUR runtime (transpiled specs import it as `vitest`); unimplemented APIs
// fail LOUD naming the API (rule 5). Fake timers live in
// scenario/upstream-fake-timers.js.

/** The scalar fast paths of deepEqual — extracted to keep the recursive
 * comparator under the 50-line function budget. */
const scalarsEqual = (a, b) => {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null || typeof a !== 'object') {
    return Number.isNaN(a) && Number.isNaN(b);
  }
  return undefined; // both non-null objects: continue in deepEqual
};

/** Deep structural equality (the expect().toEqual core), depth-guarded. */
const deepEqual = (a, b, seen = new Set(), depth = 0) => {
  if (depth > 64) failWith('harness: deepEqual depth exceeded (64) — cyclic or pathological structure');
  if (depth > 64) failWith('harness: deepEqual depth exceeded (64) — cyclic or pathological structure');
  if (scalarsEqual(a, b)) return true;
  if (a === null || b === null || typeof a !== 'object') return false;
  if (seen.has(a)) return true; // cycle: compared by identity once already
  seen.add(a);
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  return containersEqual(a, b, seen, depth);
};
const containersEqual = (a, b, seen, depth) => {
  if (Array.isArray(a)) {
    return a.length === b.length && a.every((v, i) => deepEqual(v, b[i], seen, depth + 1));
  }
  if (a instanceof Date || b instanceof Date) {
    return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();
  }
  if (a instanceof Error || b instanceof Error) {
    return a instanceof Error && b instanceof Error && a.message === b.message;
  }
  if (a instanceof Map || b instanceof Map) {
    if (!(a instanceof Map) || !(b instanceof Map) || a.size !== b.size) return false;
    for (const [k, v] of a) {
      if (!b.has(k) || !deepEqual(v, b.get(k), seen, depth + 1)) return false;
    }
    return true;
  }
  return keyedEqual(a, b, seen, depth);
};
const keyedEqual = (a, b, seen, depth) => {
  if (a instanceof Set || b instanceof Set) {
    /* Set equality is MEMBERSHIP, not insertion order (measured 2026-09-23:
     * agent-initiator asserts new Set([...signals]).toEqual(new Set([s])) —
     * the generic object compare failed it). Members compare by the same
     * deep rules; identity-only when no deep twin exists. */
    if (!(a instanceof Set) || !(b instanceof Set) || a.size !== b.size) return false;
    const rest = new Set(b);
    for (const item of a) {
      let matched = false;
      if (rest.delete(item)) continue;
      for (const candidate of rest) {
        if (deepEqual(item, candidate, seen, depth + 1)) {
          rest.delete(candidate);
          matched = true;
          break;
        }
      }
      if (!matched) return false;
    }
    return true;
  }
  if (a instanceof Set || b instanceof Set) {
    if (!(a instanceof Set) || !(b instanceof Set) || a.size !== b.size) return false;
    for (const v of a) {
      if (!b.has(v)) return false;
    }
    return true;
  }
  const ka = Object.keys(a);
  const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  return ka.every((k) => Object.prototype.hasOwnProperty.call(b, k) && deepEqual(a[k], b[k], seen, depth + 1));
  return true;
};

/** Subset-matching for toEqual/toMatchObject against asymmetric matchers. */
const matchSubset = (actual, expected, strict, seen = new Set(), depth = 0) => {
  if (expected && typeof expected === 'object' && expected.__matcher) {
    return expected.__matcher(actual);
  }
  // Identity fast path + cycle guard (measured 2026-09-23: agent-initiator
  // and scope-lifecycle compare LIVE cordis objects against themselves —
  // expected === actual at the cycle point; and cordis getters return a NEW
  // traceable proxy on every access, so a seen-SET never re-sees the same
  // instance. Identity equality terminates those cycles exactly; a depth
  // cap (deepEqual's own bound) is the backstop for distinct-but-cyclic
  // structures, where the harness deems the walked prefix equal.)
  if (actual === expected) return true;
  if (depth > 64) return true;
  if (expected === null || typeof expected !== 'object' || actual === null || typeof actual !== 'object') {
    return deepEqual(actual, expected);
  }
  // BOTH-sides-Errors compare by name + message (vitest's error equality):
  // quickjs owns `stack` as an ENUMERABLE own property where V8 hides it, so
  // the generic own-key walk failed `toEqual(new Error(m))` on key count
  // alone. A plain-shape expected (expect.objectContaining) against an Error
  // actual still walks the subset below, exactly like vitest.
  if (actual instanceof Error && expected instanceof Error) {
    if (actual.message !== expected.message) return false;
    if ((actual.name ?? 'Error') !== (expected.name ?? 'Error')) return false;
    const extraA = Object.keys(actual).filter((k) => k !== 'stack');
    const extraB = Object.keys(expected).filter((k) => k !== 'stack');
    return extraA.length === extraB.length
      && extraA.every((k) => matchSubset(actual[k], expected[k], strict, seen, depth + 1));
  }
  // An Error ACTUAL against a plain-shape expected (toMatchObject): quickjs
  // keeps `name` on the prototype (an own-key walk reads "{}"), so the subset
  // compare judges the error by its name/message face plus its own extra
  // properties. Strict toEqual keeps the generic walk (vitest fails
  // Error-vs-plain-object there too). Measured 2026-09-27:
  // ptc-runtime-node bootstrap matches {name, message} on a rejected error.
  if (actual instanceof Error && !strict) {
    const shaped = { name: actual.name ?? 'Error', message: actual.message };
    for (const key of Object.keys(expected)) {
      if (key === 'stack') continue; // engine-specific; never asserted
      const source = Object.prototype.hasOwnProperty.call(shaped, key) ? shaped : actual;
      if (!Object.prototype.hasOwnProperty.call(source, key)) return false;
      if (!matchSubset(source[key], expected[key], strict, seen, depth + 1)) return false;
    }
    return true;
  }
  if (Array.isArray(expected)) {
    if (strict && actual.length !== expected.length) return false;
    if (!Array.isArray(actual) || actual.length < expected.length) return false;
    return expected.every((v, i) => matchSubset(actual[i], v, strict, seen, depth + 1));
  }
  if (!strict && Array.isArray(actual)) return false;
  for (const key of Object.keys(expected)) {
    // toEqual's undefined-key rule (see the strict tail): an expected key
    // whose value is undefined is NOT required to exist on the actual side.
    if (strict && expected[key] === undefined) continue;
    // Non-strict (toMatchObject) reads through property ACCESS — vitest
    // matches class instances whose fields are prototype getters (the
    // fetch-values Response/Request faces); an own-key walk read "{}".
    // A property that is absent (undefined + no own key) still fails.
    if (strict) {
      if (!Object.prototype.hasOwnProperty.call(actual, key)) return false;
    } else if (actual[key] === undefined && !Object.prototype.hasOwnProperty.call(actual, key)) {
      return false;
    }
    if (!matchSubset(actual[key], expected[key], strict, seen, depth + 1)) return false;
  }
  if (strict) {
    // toEqual's undefined-key rule: keys whose value is undefined are
    // ignored on BOTH sides (vitest's equals treats {a:1} equal to
    // {a:1, nested:undefined}; toStrictEqual keeps the distinction via
    // deepEqual). Measured 2026-09-27: settings redact asserts
    // toEqual {extra, nested: undefined}.
    const actualDefined = Object.keys(actual).filter((k) => actual[k] !== undefined);
    const expectedDefined = Object.keys(expected).filter((k) => expected[k] !== undefined);
    if (actualDefined.length !== expectedDefined.length) return false;
    return actualDefined.every((k) => Object.prototype.hasOwnProperty.call(expected, k)
      && matchSubset(actual[k], expected[k], strict, seen, depth + 1));
  }
  return true;
};

class AssertionError extends Error {
  constructor(message) {
    super(message);
    this.name = 'AssertionError';
  }
}

/** Render one assertion value. JSON.stringify is NOT used for objects and
 * String() is NOT used as a fallback: they consult toJSON/toString — property
 * PROBES that dispatch through lazy test proxies (remote-mock's namespace
 * proxy registers an endpoint and throws MissingUnaryRule on any
 * toJSON/toString read — W4-N 2026-09-28) and quickjs stringify throws on
 * BigInt. The walk reads OWN KEYS ONLY (an ownKeys proxy never sees a get
 * trap, so formatting never registers endpoints), cycles render as
 * [Circular], and functions get node's inspect spellings. */
const fmt = (value, depth = 0, seen = new Set()) => {
  try {
    if (typeof value === 'string') return JSON.stringify(value);
    if (value === null) return 'null';
    if (typeof value === 'bigint') return `${value}n`;
    if (typeof value === 'function') return value.name ? `[Function: ${value.name}]` : '[Function (anonymous)]';
    if (value instanceof Error) return `${value.name ?? 'Error'}: ${value.message}`;
    if (typeof value !== 'object') return String(value); // number/boolean/undefined/symbol
    if (seen.has(value)) return '[Circular]';
    if (depth > 4) return '[Object]';
    seen.add(value);
    try {
      if (Array.isArray(value)) {
        const items = value.slice(0, 50).map((v) => fmt(v, depth + 1, seen));
        if (value.length > 50) items.push(`… ${value.length - 50} more`);
        return `[${items.join(', ')}]`;
      }
      const keys = Object.keys(value);
      const parts = keys.slice(0, 50).map((k) => `${JSON.stringify(k)}:${fmt(value[k], depth + 1, seen)}`);
      if (keys.length > 50) parts.push('…');
      return `{${parts.join(',')}}`;
    } finally {
      seen.delete(value);
    }
  } catch {
    return '[unformattable value]';
  }
};

function failWith(message) {
  throw new AssertionError(message);
}

/** Spy-call and string/collection matchers (the heavily-used surface). */
const callMatchers = (actual, check) => ({
  toHaveBeenCalled() { check(Array.isArray(actual?.mock?.calls) && actual.mock.calls.length > 0, `to have been called (calls: ${actual?.mock?.calls?.length ?? 0})`); },
  toHaveBeenCalledOnce() { check(actual?.mock?.calls?.length === 1, `to have been called once (calls: ${actual?.mock?.calls?.length ?? 0})`); },
  toHaveBeenCalledTimes(n) { check(actual?.mock?.calls?.length === n, `to have been called ${n} times (got ${actual?.mock?.calls?.length})`); },
  toHaveBeenCalledExactlyOnceWith(...expected) {
    // vitest's exactly-once + args compound (measured 2026-09-27: the
    // tool-subagent-control interrupt suite asserts the child's cancel call).
    const calls = actual?.mock?.calls ?? [];
    const ok = calls.length === 1 && calls[0].length === expected.length
      && expected.every((v, i) => matchSubset(calls[0][i], v, false));
    check(ok, `to have been called exactly once with ${fmt(expected)} (calls: ${calls.length})`);
  },
  toHaveBeenCalledWith(...expected) {
    const ok = (actual?.mock?.calls ?? []).some((call) => call.length === expected.length && expected.every((v, i) => matchSubset(call[i], v, false)));
    check(ok, `to have been called with ${fmt(expected)}`);
  },
  toHaveBeenNthCalledWith(n, ...expected) {
    const call = (actual?.mock?.calls ?? [])[n - 1];
    const ok = call !== undefined && call.length === expected.length && expected.every((v, i) => matchSubset(call[i], v, false));
    check(ok, `call #${n} to be with ${fmt(expected)} (calls: ${(actual?.mock?.calls ?? []).length})`);
  },
  toHaveBeenCalledLastWith(...expected) {
    const calls = actual?.mock?.calls ?? [];
    const last = calls[calls.length - 1];
    const ok = last !== undefined && last.length === expected.length && expected.every((v, i) => matchSubset(last[i], v, false));
    check(ok, `last call to be with ${fmt(expected)}`);
  },
  toHaveBeenLastCalledWith(...expected) {
    // the standard vitest spelling of the matcher above
    return callMatchers(actual, check).toHaveBeenCalledLastWith(...expected);
  },
  toMatch(pattern) {
    const ok = typeof actual === 'string' && (pattern instanceof RegExp ? pattern.test(actual) : actual.includes(pattern));
    check(ok, `to match ${fmt(pattern)} (got ${fmt(actual?.slice?.(0, 120))})`);
  },
  /** vitest's file-snapshot matcher without a disk: the store lives on the
   * global (one spec per runtime), writes on FIRST sight and compares on any
   * repeat within the run (R3-G1, 2026-09-28 — messages__serialize awaits
   * toMatchFileSnapshot for its degraded-replay fixture). The transpiler
   * seeds no `expected/` files, and the runtime keeps no persistent disk, so
   * the CI-strict compare-every-run mode is not reproducible here; per-run
   * stability (same input → same snapshot text) is still asserted on
   * repeats. */
  async toMatchFileSnapshot(path, _options) {
    const store = globalThis.__dshFileSnapshots ??= new Map();
    const current = runningTest ?? suite.tests[suite.tests.length - 1];
    const key = `${current?.name ?? '?'}::${path}`;
    const text = typeof actual === 'string' ? actual : fmt(actual);
    const existing = store.get(key);
    if (existing === undefined) {
      store.set(key, text);
      return check(true);
    }
    check(existing === text, `to match file snapshot ${path} (snapshot drift within the run)`);
  },
  toContainEqual(expected) {
    // matchSubset (not deepEqual): the corpus passes asymmetric matchers
    // (expect.objectContaining) nested inside toContainEqual rows.
    const ok = Array.isArray(actual) && actual.some((v) => matchSubset(v, expected, false));
    check(ok, `to contain an equal of ${fmt(expected)}`);
  },
  toBeCloseTo(n, precision = 2) {
    const ok = Math.abs(actual - n) < 10 ** -precision / 2;
    check(ok, `close to ${n} (got ${fmt(actual)})`);
  },
});

/** Ordered comparison matchers. */
const comparisonMatchers = (actual, check) => ({
  toBeGreaterThan(n) { check(actual > n, `> ${n} (got ${fmt(actual)})`); },
  toBeGreaterThanOrEqual(n) { check(actual >= n, `>= ${n} (got ${fmt(actual)})`); },
  toBeLessThan(n) { check(actual < n, `< ${n} (got ${fmt(actual)})`); },
  toBeLessThanOrEqual(n) { check(actual <= n, `<= ${n} (got ${fmt(actual)})`); },
});

/** Property-path matchers. */
const propertyMatchers = (actual, check) => ({
  toHaveProperty(key, value) {
    const parts = Array.isArray(key) ? key : key.split('.');
    let at = actual;
    for (const p of parts) {
      // vitest reads through PROPERTY ACCESS: a class instance's methods
      // (`start`/`close` on the MCP transports — the createTransport table,
      // W4-M 2026-09-28) live on the PROTOTYPE, so an own-key-only walk
      // failed every method face. Absent = undefined AND no own key.
      if (at === null || at === undefined || (at[p] === undefined && !Object.prototype.hasOwnProperty.call(at, p))) {
        check(false, `property "${key}"`);
        return;
      }
      at = at[p];
    }
    if (arguments.length > 1) {
      check(deepEqual(at, value), `property "${key}" = ${fmt(value)} (got ${fmt(at)})`);
    } else {
      check(true);
    }
  },
});

/** The toThrow family (function-throwing assertions). */
const throwMatchers = (actual, check) => ({
  toThrow(expected) {
    // A DID-THROW flag, not a null sentinel: `throw undefined` (what the
    // resolves/rejects settle wrapper throws for a settled-undefined value —
    // telemetry's resolves.not.toThrow on a void dispose) must still count
    // as a throw.
    let threw;
    let didThrow = false;
    try {
      if (typeof actual === 'function') actual();
      else return failWith('expected a function to throw');
    } catch (error) {
      didThrow = true;
      threw = error;
    }
    if (!didThrow) return check(false, 'to throw');
    if (expected === undefined) return check(true);
    // vitest's thrown-message extraction (jest-compatible): an object with a
    // `message` string compares through it; anything else (a thrown STRING —
    // boot__cmdline "rethrows a thrown value that is not an object at all" —
    // a number, undefined) stringifies and compares against that (R3-G1,
    // 2026-09-28).
    const thrownMessage = threw !== null && typeof threw === 'object' && typeof threw.message === 'string'
      ? threw.message
      : String(threw);
    // JSON-RPC errors (agentclientprotocol RequestError) keep the REAL server-
    // side error in `.data` while `message` collapses to "Internal error" —
    // surface the data in the verdict so the underlying throw is diagnosable
    // from the structured log alone (W5-Q 2026-09-28).
    const dataNote = threw !== null && typeof threw === 'object' && threw.data !== undefined
      ? ` data=${JSON.stringify(threw.data).slice(0, 300)}`
      : '';
    if (typeof expected === 'string') return check(thrownMessage.includes(expected), `throw message containing "${expected}" (got "${thrownMessage}")${dataNote}`);
    // The got-message echo stays in the regex arm too: a bare "matching /…/"
    // verdict hides which arm of an it.each table drifted (acp bridge's
    // mcpServers validation table, W3-J 2026-09-27).
    if (expected instanceof RegExp) return check(expected.test(thrownMessage), `throw message matching ${expected} (got "${thrownMessage}")${dataNote}`);
    // A thrown-in ERROR INSTANCE (jest/vitest contract): compared by MESSAGE
    // (and identity), not by instanceof — the product may re-wrap an equal
    // message across a catch boundary, and jest explicitly specifies message
    // equality for this form (measured 2026-09-28: llm-pi-ai config's
    // "propagates unexpected catalog failures").
    if (expected instanceof Error) {
      return check(threw === expected || thrownMessage === expected.message,
        `throw with message "${expected.message}" (got "${thrownMessage}")`);
    }
    if (typeof expected === 'object') return check(matchSubset(threw, expected, false), `throw matching ${fmt(expected)}`);
    check(threw instanceof expected, `throw ${expected?.name}`);
  },
  toThrowError(expected) {
    // vitest alias: toThrowError([message]) — same contract as toThrow
    return throwMatchers(actual, check).toThrow(expected);
  },
  toSatisfy(predicate) {
    check(Boolean(predicate(actual)), `to satisfy ${fmt(predicate)}`);
  },
});

/** Identity/truthiness matchers. */
const identityMatchers = (actual, check) => ({
  toBeInstanceOf(cls) { check(actual instanceof cls, `instance of ${cls?.name}`); },
  toBeNull() { check(actual === null, `null (got ${fmt(actual)})`); },
  toBeUndefined() { check(actual === undefined, `undefined (got ${fmt(actual)})`); },
  toBeDefined() { check(actual !== undefined, 'defined'); },
  toBeTruthy() { check(Boolean(actual), 'truthy'); },
  toBeFalsy() { check(Boolean(actual) === false, 'falsy'); },
  toBeNaN() { check(Number.isNaN(actual), 'NaN'); },
  toBeTypeOf(expected) {
    const got = actual === null ? 'null' : typeof actual;
    check(got === expected || (expected === 'function' && typeof actual === 'function'), `type of ${fmt(expected)} (got ${fmt(got)})`);
  },
});

/** The .resolves/.rejects chains live in shims/expect-async-chain.js. */

/** The expect() chain. The second parameter is vitest's optional custom
 * failure MESSAGE (`expect(actual, message)`) — measured 2026-09-27: treating
 * a string second argument as the negation flag (its old role in the
 * internal resolves/rejects chain) inverted every assertion of a two-arg
 * expect, so `expect(x, id).toBe(true)` failed as "expected NOT to be true".
 * A string here is a failure PREFIX; the boolean stays the negation flag. */
const makeExpect = (actual, negatedOrMessage = false, customMessage = '') => {
  // The exported expect() is this function, so vitest's `expect(actual,
  // message)` lands the message in the SECOND slot; the boolean form is how
  // the internal .not/.resolves/.rejects machinery re-enters.
  let negated = negatedOrMessage === true;
  let message = customMessage;
  if (typeof negatedOrMessage === 'string') message = negatedOrMessage;
  const prefix = typeof message === 'string' && message.length > 0
    ? `${message}: `
    : '';
  const check = (ok, description) => {
    if (negated ? ok : !ok) {
      failWith(`${prefix}expected ${negated ? 'NOT ' : ''}${description}`);
    }
  };
  const api = {
    ...callMatchers(actual, check),
    ...comparisonMatchers(actual, check),
    toBe(expected) { check(Object.is(actual, expected), `to be ${fmt(expected)} (got ${fmt(actual)})`); },
    toEqual(expected) { check(matchSubset(actual, expected, true), `to equal ${fmt(expected)} (got ${fmt(actual)})`); },
    toStrictEqual(expected) { check(deepEqual(actual, expected), `to strictly equal ${fmt(expected)}`); },
    toMatchObject(expected) { check(matchSubset(actual, expected, false), `to match ${fmt(expected)} (got ${fmt(actual)})`); },
    toContain(expected) {
      // Arrays use SAME-VALUE membership (vitest's toContain is identity —
      // deep equality would find ANY structurally-equal member, which broke
      // the deque release test where two distinct {} members are
      // indistinguishable). Strings substring, Sets has(), asymmetric
      // matchers still apply.
      let ok = false;
      if (typeof actual === 'string') ok = actual.includes(expected);
      else if (actual instanceof Set) ok = actual.has(expected);
      else if (Array.isArray(actual)) {
        ok = actual.some((v) => (expected && typeof expected === 'object' && expected.__matcher)
          ? expected.__matcher(v)
          : Object.is(v, expected));
      }
      check(ok, `to contain ${fmt(expected)}`);
    },
    toHaveLength(n) { check(actual?.length === n, `length ${n} (got ${fmt(actual?.length)})`); },
    // vitest's inline snapshot: the stored template is dedented (leading
    // newline dropped, common indentation stripped, trailing blank lines
    // trimmed) and a string actual serializes quoted with its real newlines
    // kept (the terminal tools PTC output-map projection is the only corpus
    // user — W4-N 2026-09-28).
    toMatchInlineSnapshot(expected) {
      if (typeof expected !== 'string') {
        check(false, 'inline snapshot: no stored snapshot (vitest write mode is unsupported here)');
        return;
      }
      let body = expected.startsWith('\n') ? expected.slice(1) : expected;
      const lines = body.split('\n');
      while (lines.length > 0 && lines[lines.length - 1].trim() === '') lines.pop();
      const indents = lines.filter((l) => l.trim() !== '').map((l) => l.match(/^ */)[0].length);
      const indent = indents.length > 0 ? Math.min(...indents) : 0;
      const dedented = lines.map((l) => l.slice(indent)).join('\n');
      const serialized = typeof actual === 'string' ? `"${actual}"` : fmt(actual);
      check(dedented === serialized, `to match the inline snapshot (got ${serialized.slice(0, 600)})`);
    },
    ...identityMatchers(actual, check),
    ...propertyMatchers(actual, check),
    ...throwMatchers(actual, check),
    // vitest unwraps a FUNCTION subject by calling it before awaiting
    // (`typeof obj === "function" ? obj() : obj`) — expect(async fn).resolves
    // / .rejects is the corpus's dominant form (api remotes.host, session).
    resolves: makeAsyncChain(() => Promise.resolve(typeof actual === 'function' ? actual() : actual), negated, true, message),
    rejects: makeAsyncChain(() => Promise.resolve(typeof actual === 'function' ? actual() : actual).then(
      () => failWith('expected the promise to reject, but it resolved'),
      (error) => error,
    ), negated, false, message),
  };
  // .not is LAZY: constructing it eagerly would recurse (each negated
  // matcher set builds its own .not, forever). The custom failure MESSAGE
  // rides along (W4-N 2026-09-28: vitest's `expect(x, msg).not.toContain()`
  // throws with msg as the failure text and storage-policy's guard asserts
  // that message via rejects.toThrow — dropping it broke the match).
  let negatedApi = null;
  Object.defineProperty(api, 'not', {
    get: () => {
      if (negatedApi === null) negatedApi = makeExpect(actual, !negated, message);
      return negatedApi;
    },
  });
  return api;
};
const makeAsyncChain = attachAsyncChain(makeExpect, failWith);

/** The vi.fn mock core: a calls/results ledger plus the implementation
 * queue; the *Once family prepends a one-shot implementation consumed
 * before the standing one. A REGULAR function so spyOn-wrapped originals
 * see the call-site receiver — vitest's spy forwards `this`
 * (measured 2026-09-23: system-prompt-admission spies adapter.resolveModel,
 * whose body reads this.reasoning; an arrow spy broke every request). */
const makeMockFn = (impl) => {
  const onceQueue = [];
  const originalImpl = impl; // mockReset restores the creation implementation
  const f = function (...args) {
    f.mock.calls.push(args);
    // vitest's mock.instances ledger: the receiver of each call (the
    // controller.client download spec reads click.mock.instances[0] to
    // inspect the anchor the product mutated).
    f.mock.instances.push(this);
    f.mock.invocationCallOrder.push(++mockCallSeq);
    const next = onceQueue.length > 0 ? onceQueue.shift() : impl;
    try {
      const value = next ? next.apply(this, args) : undefined;
      f.mock.results.push({ type: 'return', value });
      return value;
    } catch (error) {
      f.mock.results.push({ type: 'throw', value: error });
      throw error;
    }
  };
  f.mock = { calls: [], instances: [], results: [], invocationCallOrder: [] };
  f.mockImplementation = (next) => { impl = next; return f; };
  f.mockImplementationOnce = (next) => { onceQueue.push(next); return f; };
  f.mockReturnValue = (value) => { impl = () => value; return f; };
  f.mockReturnValueOnce = (value) => { onceQueue.push(() => value); return f; };
  f.mockResolvedValue = (value) => { impl = () => Promise.resolve(value); return f; };
  f.mockResolvedValueOnce = (value) => { onceQueue.push(() => Promise.resolve(value)); return f; };
  f.mockRejectedValue = (value) => { impl = () => Promise.reject(value); return f; };
  f.mockRejectedValueOnce = (value) => { onceQueue.push(() => Promise.reject(value)); return f; };
  // vitest's reset family (W4-N 2026-09-28, remote-mock's proxy spec):
  // mockClear clears the CALL LEDGERS only — queued one-shot overrides
  // survive it ("keeps queued overrides on mockClear"); mockReset clears
  // the ledgers AND the queued overrides AND restores the ORIGINAL
  // implementation the mock was created with ("restores the live default
  // rule on mockReset" — the vendored remote-mock's fn was created around
  // its default-rule dispatcher, so a reset re-arms that dispatcher).
  f.mockClear = () => {
    f.mock.calls.length = 0;
    f.mock.instances.length = 0;
    f.mock.results.length = 0;
    f.mock.invocationCallOrder.length = 0;
    return f;
  };
  f.mockReset = () => {
    f.mockClear();
    onceQueue.length = 0;
    impl = originalImpl;
    return f;
  };
  return f;
};

let mockCallSeq = 0; // vitest's mock.invocationCallOrder: process-wide call sequence

const fakeTimerState = {};

/** vi subset; the mock and timer APIs fail loud (loader-level / no seam). */
const viApi = {
  fn: makeMockFn,
  isMockFunction: (v) => typeof v === 'function' && v.mock !== undefined,
  spyOn(object, key) {
    const original = object[key];
    const spy = makeMockFn(typeof original === 'function' ? original : undefined);
    spy.mockRestore = () => { object[key] = original; };
    object[key] = spy;
    return spy;
  },
  stubGlobal(name, value) {
    if (!viApi._globalStubs) viApi._globalStubs = [];
    // vitest installs stubs through defineProperty and restores the original
    // PROPERTY DESCRIPTOR — not by read-then-assign. The distinction is
    // load-bearing: a stubbed global may be (or become) a getter-only
    // accessor (recovery.client's "storage denied" fixture defines a
    // throwing localStorage getter), where a value read throws at stub time
    // and a value write cannot undo the accessor. Descriptor capture + a
    // defineProperty install keeps every shape stubbable and restorable.
    const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
    Object.defineProperty(globalThis, name, {
      value, writable: true, enumerable: true, configurable: true,
    });
    const restore = { mockRestore: () => {
      if (descriptor === undefined) delete globalThis[name];
      else Object.defineProperty(globalThis, name, descriptor);
    } };
    viApi._globalStubs.push(restore);
    return restore;
  },
  stubEnv(name, value) {
    if (!viApi._envStubs) viApi._envStubs = {};
    if (!(name in viApi._envStubs)) viApi._envStubs[name] = process.env[name];
    process.env[name] = value;
  },
  unstubAllEnvs() {
    for (const [name, value] of Object.entries(viApi._envStubs ?? {})) {
      if (value === undefined) delete process.env[name];
      else process.env[name] = value;
    }
    viApi._envStubs = {};
  },
  unstubAllGlobals() {
    // Each entry is a {mockRestore} record (vitest shape) — call the METHOD,
    // not the record (measured 2026-09-27: "not a function" on every spec
    // using vi.stubGlobal + unstubAllGlobals).
    for (const restore of viApi._globalStubs ?? []) restore.mockRestore?.();
    viApi._globalStubs = [];
  },
  restoreAllMocks() { /* spies restore on their own handles */ },
  clearAllMocks() { /* spies clear on their own handles */ },
  mocked: (v) => v,
  hoisted: (factory) => factory(),
  mock: () => failWith('harness: vi.mock is not implemented (loader-level interception) — the transpiler excludes specs that need it'),
  ...fakeTimerApi(fakeTimerState),
};
attachViWaits(viApi, failWith);

// ---- collection -----------------------------------------------------------

const suite = { tests: [], before: [], after: [], beforeEach: [], afterEach: [] };
let currentDescribe = [];

const fullName = (name) => [...currentDescribe, name].join(' > ');

export const describe = (name, optionsOrFactory, maybeFactory) => {
  // vitest's (name, options, factory) spelling (the remote-mock proxy-types
  // spec passes { timeout }: the middle argument is optional).
  const factory = typeof optionsOrFactory === 'function' ? optionsOrFactory : maybeFactory;
  currentDescribe.push(name);
  factory();
  currentDescribe.pop();
};
describe.skip = () => { /* counted at transpile time */ };
describe.only = (name, factory) => describe(name, factory);
// vitest's concurrent suites run their tests in parallel; the runtime is
// single-threaded serial (D2), so the face runs them sequentially — the
// acp-snapshot suite selects describe.concurrent for replay mode (W5-T).
describe.concurrent = (name, optionsOrFactory, maybeFactory) => describe(name, optionsOrFactory, maybeFactory);

export const it = (name, fn) => {
  suite.tests.push({ name: fullName(name), fn, hooks: { beforeEach: [...suite.beforeEach], afterEach: [...suite.afterEach] } });
};
it.skip = () => {};
it.only = it;
it.each = (table) => (name, fn) => {
  for (const row of table) {
    const args = Array.isArray(row) ? row : [row];
    it(`${name.replace(/\$\{[^}]+\}/g, () => '').trim()} [${args.map(fmt).join(',')}]`, () => fn(...args));
  }
};
/** vitest's it.for: a cases table collected once, each case runs the test
 * fn as (caseValue, ctx) — the ctx carries a test-scoped onTestFinished
 * (the files-api redirect-refusal arms drive exactly this shape). */
it.for = (table) => (name, fn) => {
  for (const row of table) {
    const value = Array.isArray(row) ? row[0] : row;
    it(`${name.replace('%s', String(value)).trim()} [${String(value)}]`, () => {
      let cleanup = null;
      try {
        fn(value, { onTestFinished: (fn2) => { cleanup = fn2; } });
      } finally {
        if (typeof cleanup === 'function') {
          try { cleanup(); } catch { /* a cleanup failure must not mask the test's own verdict */ }
        }
      }
    });
  }
};
export const test = it;
export const beforeEach = (fn) => { suite.beforeEach.push(fn); };
export const afterEach = (fn) => { suite.afterEach.push(fn); };
attachEachForms(describe, it);

export const beforeAll = (fn) => { suite.before.push(fn); };
export const afterAll = (fn) => { suite.after.push(fn); };
/** vitest's onTestFinished: register cleanup for the CURRENTLY-RUNNING test
 * (or the collection tail when called at module scope — the spec's intent
 * is teardown-after-test either way). */
export const onTestFinished = (fn) => {
  const last = suite.tests[suite.tests.length - 1];
  if (last !== undefined) {
    last.hooks.afterEach.push(fn);
  } else {
    suite.afterEach.push(fn);
  }
};
export const expect = Object.assign(makeExpect, {
  extend: () => failWith('harness: expect.extend is not implemented'),
  /** expect.soft: vitest records and continues; the harness has no
   * end-of-test collector, so soft asserts immediately — the test's verdict
   * (fail) is identical, only later assertions in the same test don't run. */
  soft: (value) => makeExpect(value),
  fail: (message = 'expect.fail()') => failWith(String(message)),
  unreachable: (message = 'expected unreachable path') => failWith(`unreachable: ${String(message)}`),
  anything: () => ({ __matcher: () => true }),
  any: (cls) => ({ __matcher: (v) => typeof v === cls?.name?.toLowerCase() || v instanceof cls }),
  objectContaining: (shape) => ({ __matcher: (v) => matchSubset(v, shape, false) }),
  arrayContaining: (shape) => ({ __matcher: (v) => Array.isArray(v) && shape.every((s) => v.some((x) => matchSubset(x, s, false))) }),
  stringContaining: (s) => ({ __matcher: (v) => typeof v === 'string' && v.includes(s) }),
  stringMatching: (r) => ({ __matcher: (v) => typeof v === 'string' && r.test(v) }),
  closeTo: (n, precision = 2) => ({ __matcher: (v) => Math.abs(v - n) < 10 ** -precision / 2 }),
  hasProperty: (key) => ({ __matcher: (v) => v != null && Object.prototype.hasOwnProperty.call(v, key) }),
});
attachExpectPoll(expect, makeExpect, failWith);
export const vi = viApi;

const typeChain = new Proxy(function typeProbe() {}, {
  get: (_t, key) => (typeof key === 'string' ? typeChain : undefined),
  apply: () => typeChain,
});
export const expectTypeOf = () => typeChain;

/** Run everything the imported specs collected; report per test to the
 * caller's sink. Returns {passed, failed, skipped, failures}. A test that
 * never settles is the suite's hang class (no timer seam to cut it short) —
 * the sink sees its 'start' before it runs, so the stream names the exact
 * test a hang froze on. */
export const runCollected = async (sink) => {
  const report = { passed: 0, failed: 0, skipped: 0, failures: [] };
  // Suite-level hooks reject with whatever the spec threw — including bare
  // null/undefined (the otel egress afterAll rejected with null, which
  // escaped as a scenario failure with the reason string "null" and no
  // attribution). Wrap both ends: the hook's identity and the thrown value
  // are named, never silently re-thrown (rule 5).
  const suiteHookError = (phase, error) => new Error(
    `${phase} hook failed: ${error === null ? 'null (rejection with null)' : error instanceof Error ? error.message : String(error)}`,
  );
  for (const setup of suite.before) {
    try {
      await setup();
    } catch (error) {
      throw suiteHookError('beforeAll', error);
    }
  }
  for (const t of suite.tests) {
    if (typeof t.fn !== 'function') { report.skipped += 1; sink(t.name, 'skipped'); continue; }
    sink(t.name, 'start');
    runningTest = t;
    try {
      for (const hook of t.hooks.beforeEach) await hook();
      // vitest hands every test fn a CONTEXT as its first argument — tests
      // that destructure it (`async ({ skip }) => …`) throw
      // "Cannot convert undefined or null to object" when it is missing
      // (stream-rebind). The context face is the documented subset: skip()
      // raises a marker the runner classifies as 'skipped' (vitest never
      // counts a context-skip a failure).
      // Per-test abort signal: vitest hands each test fn a context whose
      // `signal` aborts when the test finishes; tests thread it into
      // deadline helpers and call signal.throwIfAborted() mid-body.
      const controller = new AbortController();
      try {
        await t.fn({
          skip: (note) => {
            const skipError = new Error(note ?? 'skipped by test context');
            skipError.__dshTestContextSkip = true;
            throw skipError;
          },
          // vitest's `task` face: the running test's handle — task.timeout
          // is the test's time budget in ms (specs pass it as a DEADLINE
          // value: waitForFile(marker, task.timeout, signal)); budget
          // re-arming stays on TestRunner.getCurrentTest().timeout(ms).
          task: {
            get name() { return t.name; },
            get timeout() { return t.timeoutMs ?? 5000; },
          },
          signal: controller.signal,
        });
      } finally {
        controller.abort();
      }
      report.passed += 1;
      sink(t.name, 'pass');
    } catch (error) {
      if (error?.__dshTestContextSkip) {
        report.skipped += 1;
        sink(t.name, 'skipped');
        runningTest = null;
        continue;
      }
      report.failed += 1;
      report.failures.push({
        name: t.name,
        message: error?.message ?? String(error),
        stack: String(error?.stack ?? '').split('\n').slice(1, 5).join(' | '),
      });
      const launchEnv = (() => {
        try { const raw = globalThis.__dshLaunchEnv?.(); return raw ? JSON.parse(raw) : {}; } catch { return {}; }
      })();
      if (globalThis.__DSH_LOG_SINK__ && launchEnv.DSH_R3E_DEBUG === '1') {
        const rawJson = (() => { try { return JSON.stringify(error); } catch { return String(error); } })();
        globalThis.__DSH_LOG_SINK__(JSON.stringify({ scenario: 'upstream.suite', event: 'debug/failure', name: t.name.slice(0, 120), cls: error?.constructor?.name, stack: String(error?.stack ?? '').slice(0, 900), raw: rawJson }));
      }
      sink(t.name, 'fail', error?.message ?? String(error));
    } finally {
      runningTest = null;
      for (const hook of t.hooks.afterEach) {
        try { await hook(); } catch { /* afterEach failures do not mask the verdict */ }
      }
    }
  }
  for (const teardown of suite.after) {
    try {
      await teardown();
    } catch (error) {
      // vitest counts an afterAll failure as a suite error, not a test
      // failure — surface it as its own failure row AND a named rejection,
      // so the scenario verdict carries the hook's name instead of "null".
      report.failed += 1;
      const named = suiteHookError('afterAll', error);
      report.failures.push({ name: 'afterAll', message: named.message, stack: String(error?.stack ?? '').split('\n').slice(1, 5).join(' | ') });
      sink('afterAll', 'fail', named.message);
      throw named;
    }
  }
  return report;
};

/** vitest's TestRunner face — the corpus specs ask the runner for the test
 * they are INSIDE (`TestRunner.getCurrentTest().timeout(ms)` re-arms that
 * test's time budget). The runtime has no wall-clock seam to enforce a
 * budget (the runCollected hang note above), so the request is recorded on
 * the test record and surfaced through the sink instead of being silently
 * dropped. Outside a run (collection time) the CURRENT test is the last one
 * collected, which is what module-scope callers mean. */
let runningTest = null;
export const TestRunner = {
  getCurrentTest() {
    const current = runningTest ?? suite.tests[suite.tests.length - 1];
    if (current === undefined) failWith('harness: TestRunner.getCurrentTest() — no test is running or collected');
    return {
      timeout: (ms) => { current.timeoutMs = ms; },
      name: current.name,
    };
  },
};

/** Reset collection (the driver runs one spec module per runtime). */
export const resetCollection = () => {
  suite.tests.length = 0;
  suite.before.length = 0;
  suite.after.length = 0;
  suite.beforeEach.length = 0;
  suite.afterEach.length = 0;
  currentDescribe.length = 0;
};